const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    target: body.target || 'unknown',
    total: body.total || 0,
    critical: body.critical || 0,
    high: body.high || 0,
    medium: body.medium || 0,
    vulnerabilities: body.vulnerabilities || []
  }
}];

const ollamaResponse = $input.first().json.response;
const scanData = $('Parse Results').first().json;

let analysis;
try {
  const jsonMatch = ollamaResponse.match(/\{[\s\S]*\}/);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : { risk_level: 'unknown', summary: ollamaResponse };
} catch(e) {
  analysis = { risk_level: 'unknown', summary: ollamaResponse };
}

return [{
  json: {
    target: scanData.target,
    timestamp: new Date().toISOString(),
    scan_summary: {
      total: scanData.total || 0,
      critical: scanData.critical || 0,
      high: scanData.high || 0,
      medium: scanData.medium || 0
    },
    ai_analysis: analysis,
    vulnerabilities: scanData.vulnerabilities || []
  }
}];
